pub unsafe extern "C" fn handle_nvim_buf_delete(
    channel_id: uint64_t,
    args: Array,
    _arena: *mut Arena,
    error: *mut Error,
) -> Object {
    unsafe {
        log_invoke(
            c"handle_nvim_buf_delete",
            c"RPC: ch %lu: invoke nvim_buf_delete",
            line!() as c_int,
            channel_id,
        );
        if args.size != 2 as size_t {
            wrong_arity(error, 2, args.size);
            return NIL;
        }
        let item = *args.items.add(0);
        let Some(arg_1) = as_handle(item, kObjectTypeBuffer) else {
            wrong_type(error, 1, c"nvim_buf_delete", c"Buffer");
            return NIL;
        };
        let item = *args.items.add(1);
        let mut arg_2: KeyDict_buf_delete = core::mem::zeroed();
        if item.type_0 == kObjectTypeDict {
            if !api_dict_to_keydict(
                (&raw mut arg_2).cast(),
                Some(KeyDict_buf_delete_get_field),
                item.data.dict,
                error,
            ) {
                return NIL;
            }
        } else if !is_empty_array(item) {
            wrong_type(error, 2, c"nvim_buf_delete", c"Dict(buf_delete) *");
            return NIL;
        }
        if text_locked() {
            api_set_error(
                error,
                kErrorTypeException,
                c"%s".as_ptr(),
                get_text_locked_msg(),
            );
            return NIL;
        }
        nvim_buf_delete(arg_1, &raw mut arg_2, error);
        if (*error).type_0 != kErrorTypeNone {
            return NIL;
        }
        NIL
    }
}

